const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const blackSea = ee.Geometry.Polygon([
    [[28.0, 46.5], [28.0, 40.5], [42.0, 40.5], [42.0, 46.5], [28.0, 46.5]]
  ]);

  const date1 = '2022-05-20';
  const date2 = '2022-06-20';

  // 2. Data Acquisition
  function getBrightnessImage(date) {
    const col = ee.ImageCollection('MODIS/061/MOD09GA')
      .filterBounds(blackSea)
      .filterDate(date, ee.Date(date).advance(1, 'day'));

    if (col.size().getInfo() === 0) {
      return null;
    }

    const image = col.first();

    // Calculate brightness as mean of visible bands (sur_refl_b01, b04, b03 = red, green, blue)
    const brightness = image.select(['sur_refl_b01', 'sur_refl_b04', 'sur_refl_b03'])
      .reduce(ee.Reducer.mean())
      .rename('brightness');

    // Mask clouds using state_1km band
    const cloudMask = image.select('state_1km').bitwiseAnd(1).eq(0);
    const landMask = image.select('state_1km').bitwiseAnd(8).eq(0); // Water flag

    return brightness.updateMask(cloudMask.and(landMask));
  }

  const img1 = getBrightnessImage(date1);
  const img2 = getBrightnessImage(date2);

  // Check for empty collections
  if (!img1 || !img2) {
    console.log(`May 20 Images: ${img1 ? '1' : '0'}`);
    console.log(`June 20 Images: ${img2 ? '1' : '0'}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean brightness
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: blackSea,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: blackSea,
    scale: 1000,
    maxPixels: 1e9
  });

  const brightness1 = stats1.get('brightness').getInfo();
  const brightness2 = stats2.get('brightness').getInfo();

  // Check for no valid pixels
  if (brightness1 === null || brightness2 === null) {
    console.log("May brightness: null");
    console.log("June brightness: null");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (isNaN(brightness1) || isNaN(brightness2) || brightness1 === undefined || brightness2 === undefined) {
    console.log("May brightness: invalid");
    console.log("June brightness: invalid");
    console.log("<answer>C3</answer>");
    return;
  }

  // 4. Output results and final answer
  console.log(`May brightness: ${brightness1.toFixed(4)}`);
  console.log(`June brightness: ${brightness2.toFixed(4)}`);
  console.log(`Difference: ${(brightness2 - brightness1).toFixed(4)}`);

  if (brightness2 > brightness1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
